//! Operation tests on PDFs generated by [`crate::testing`].

use crate::testing::*;
use crate::*;

fn open(bytes: &[u8]) -> Pdf {
    Pdf::from_bytes(bytes, None).unwrap()
}

fn ranges(s: &str) -> PageRanges {
    PageRanges::parse(s).unwrap()
}

/// Save, reload, and return each page's (width, rotation): the width tells
/// which sample page it is.
fn layout(pdf: &mut Pdf) -> Vec<(u32, i64)> {
    let bytes = pdf.to_bytes().unwrap();
    let info = info(&bytes, None).unwrap();
    info.pages
        .iter()
        .map(|p| {
            let w = if p.rotation % 180 == 90 {
                p.height
            } else {
                p.width
            };
            ((w - 600.0).round() as u32, p.rotation)
        })
        .collect()
}

fn order(pdf: &mut Pdf) -> Vec<u32> {
    layout(pdf).into_iter().map(|(k, _)| k).collect()
}

fn content_text(pdf: &Pdf, page: u32) -> String {
    let doc = pdf.document();
    let id = doc.get_pages()[&page];
    let bytes = doc.get_page_content(id);
    String::from_utf8_lossy(&bytes).into_owned()
}

#[test]
fn opens_and_counts_pages() {
    let pdf = open(&sample_pdf(4));
    assert_eq!(pdf.page_count(), 4);
    assert!(!pdf.was_encrypted());
}

#[test]
fn rejects_garbage() {
    let e = Pdf::from_bytes(b"hello", None).unwrap_err();
    assert!(matches!(e, Error::NotPdf(_)), "{e}");
}

#[test]
fn extract_keeps_written_order_and_repeats() {
    let mut pdf = open(&sample_pdf(5));
    extract(&mut pdf, &ranges("4,1-2,4")).unwrap();
    assert_eq!(order(&mut pdf), [4, 1, 2, 4]);
    // Pages 3 and 5 are gone from the file, not just the tree.
    let text: String = (1..=4).map(|p| content_text(&pdf, p)).collect();
    assert!(
        !text.contains("Page 3") && !text.contains("Page 5"),
        "{text}"
    );
}

#[test]
fn delete_removes_pages_and_unused_objects() {
    let mut pdf = open(&sample_pdf(6));
    let before = pdf.document().objects.len();
    assert_eq!(delete(&mut pdf, &ranges("2,4-5")).unwrap(), 3);
    assert_eq!(order(&mut pdf), [1, 3, 6]);
    // Three pages and their content streams are gone.
    assert!(pdf.document().objects.len() <= before - 6);
    let text: String = (1..=3).map(|p| content_text(&pdf, p)).collect();
    assert!(
        !text.contains("Page 2") && !text.contains("Page 4"),
        "{text}"
    );
}

#[test]
fn delete_refuses_to_remove_every_page() {
    let mut pdf = open(&sample_pdf(3));
    let e = delete(&mut pdf, &ranges("1-")).unwrap_err();
    assert!(e.to_string().contains("all 3 pages"), "{e}");
}

#[test]
fn reorder_needs_every_page_once() {
    let mut pdf = open(&sample_pdf(4));
    reorder(&mut pdf, &ranges("4,2,3,1")).unwrap();
    assert_eq!(order(&mut pdf), [4, 2, 3, 1]);

    let mut pdf = open(&sample_pdf(4));
    reorder(&mut pdf, &ranges("4-1")).unwrap();
    assert_eq!(order(&mut pdf), [4, 3, 2, 1]);

    let mut pdf = open(&sample_pdf(4));
    let e = reorder(&mut pdf, &ranges("1,1,2")).unwrap_err().to_string();
    assert!(e.contains("missing 3-4") && e.contains("repeated 1"), "{e}");
}

#[test]
fn rotate_adds_to_existing_rotation() {
    let mut pdf = open(&sample_pdf(3));
    assert_eq!(rotate(&mut pdf, &ranges("1,3"), 90).unwrap(), 2);
    assert_eq!(layout(&mut pdf), [(1, 90), (2, 0), (3, 90)]);
    rotate(&mut pdf, &PageRanges::all(), 270).unwrap();
    assert_eq!(layout(&mut pdf), [(1, 0), (2, 270), (3, 0)]);
    rotate(&mut pdf, &ranges("2"), -90).unwrap();
    assert_eq!(layout(&mut pdf)[1], (2, 180));
    assert!(rotate(&mut pdf, &ranges("1"), 45).is_err());
}

#[test]
fn inherited_attributes_survive_page_moves() {
    // Rotation and resources live on the tree root in this sample.
    let mut pdf = open(&sample_pdf_inherited(3));
    assert_eq!(layout(&mut pdf), [(1, 90), (2, 90), (3, 90)]);
    reorder(&mut pdf, &ranges("3,1,2")).unwrap();
    assert_eq!(layout(&mut pdf), [(3, 90), (1, 90), (2, 90)]);
    let doc = pdf.document();
    for id in doc.get_pages().into_values() {
        assert!(doc.get_dictionary(id).unwrap().has(b"Resources"));
    }
    rotate(&mut pdf, &ranges("1"), 90).unwrap();
    assert_eq!(layout(&mut pdf)[0], (3, 180));
}

#[test]
fn split_by_groups_writes_self_contained_parts() {
    let pdf = open(&sample_pdf(5));
    let mut parts = Vec::new();
    split(
        &pdf,
        &ranges("1-2,3,4-").resolve_groups(5).unwrap(),
        |mut part| {
            let bytes = part.pdf.to_bytes()?;
            // Each part reloads on its own and holds only its pages.
            let mut again = Pdf::from_bytes(&bytes, None)?;
            parts.push((part.pages.clone(), order(&mut again), bytes.len()));
            Ok(())
        },
    )
    .unwrap();
    assert_eq!(parts.len(), 3);
    assert_eq!(parts[0].0, [1, 2]);
    assert_eq!(parts[0].1, [1, 2]);
    assert_eq!(parts[1].1, [3]);
    assert_eq!(parts[2].1, [4, 5]);
}

#[test]
fn split_parts_keep_inherited_attributes_and_info() {
    let pdf = open(&sample_pdf_inherited(2));
    let mut seen = Vec::new();
    split(&pdf, &every(2, 1).unwrap(), |mut part| {
        let bytes = part.pdf.to_bytes()?;
        let i = info(&bytes, None)?;
        seen.push((i.pages.len(), i.pages[0].rotation, i.title.clone()));
        Ok(())
    })
    .unwrap();
    assert_eq!(
        seen,
        vec![
            (1, 90, Some("Sample".into())),
            (1, 90, Some("Sample".into()))
        ]
    );
}

#[test]
fn every_n_chunks() {
    assert_eq!(every(5, 2).unwrap(), vec![vec![1, 2], vec![3, 4], vec![5]]);
    assert!(every(5, 0).is_err());
}

#[test]
fn merge_appends_pages_in_order() {
    let a = open(&sample_pdf(2));
    let mut b = open(&sample_pdf(3));
    extract(&mut b, &ranges("3,1")).unwrap();
    let c = open(&sample_pdf_inherited(1));
    let mut merged = merge(a, vec![b, c]).unwrap();
    assert_eq!(
        layout(&mut merged),
        [(1, 0), (2, 0), (3, 0), (1, 0), (1, 90)]
    );
    // Every page still has its text after renumbering.
    for p in 1..=5 {
        assert!(content_text(&merged, p).contains("Page"), "page {p}");
    }
}

#[test]
fn info_reports_sizes_and_metadata() {
    let bytes = sample_pdf(2);
    let i = info(&bytes, None).unwrap();
    assert_eq!(i.pages.len(), 2);
    assert_eq!(i.pages[0].width, 601.0);
    assert_eq!(i.pages[0].height, 800.0);
    assert_eq!(i.title.as_deref(), Some("Sample"));
    assert_eq!(i.author.as_deref(), Some("Kantor tests"));
    assert!(!i.encrypted);
    assert_eq!(i.file_size, bytes.len());
}

#[test]
fn paper_names() {
    let a4 = PageInfo {
        width: 595.0,
        height: 842.0,
        rotation: 0,
    };
    assert_eq!(a4.paper_name().as_deref(), Some("A4"));
    let letter_land = PageInfo {
        width: 792.0,
        height: 612.0,
        rotation: 0,
    };
    assert_eq!(
        letter_land.paper_name().as_deref(),
        Some("Letter landscape")
    );
}

#[test]
fn encrypted_pdfs_need_a_password() {
    let bytes = sample_pdf_encrypted(2, "owner", "secret");
    assert!(matches!(
        Pdf::from_bytes(&bytes, None),
        Err(Error::Encrypted)
    ));
    assert!(matches!(
        Pdf::from_bytes(&bytes, Some("nope")),
        Err(Error::WrongPassword)
    ));
    let mut pdf = Pdf::from_bytes(&bytes, Some("secret")).unwrap();
    assert!(pdf.was_encrypted());
    assert_eq!(pdf.page_count(), 2);
    // The result is written without encryption.
    let out = pdf.to_bytes().unwrap();
    let reopened = Pdf::from_bytes(&out, None).unwrap();
    assert!(content_text(&reopened, 1).contains("Page 1"));

    let i = info(&bytes, None).unwrap();
    assert!(i.encrypted);
    assert!(!i.readable);
    let i = info(&bytes, Some("secret")).unwrap();
    assert!(i.encrypted && i.readable);
    assert_eq!(i.pages.len(), 2);
    assert_eq!(i.title.as_deref(), Some("Sample"));
}

#[test]
fn encrypted_with_empty_user_password_still_needs_the_flag() {
    let bytes = sample_pdf_encrypted(1, "owner", "");
    assert!(matches!(
        Pdf::from_bytes(&bytes, None),
        Err(Error::Encrypted)
    ));
    assert_eq!(Pdf::from_bytes(&bytes, Some("")).unwrap().page_count(), 1);
    let i = info(&bytes, None).unwrap();
    assert!(i.encrypted && i.readable);
}

#[test]
fn watermark_stamps_selected_pages() {
    let mut pdf = open(&sample_pdf(3));
    let opts = WatermarkOptions {
        text: "DRAFT".into(),
        ..Default::default()
    };
    assert_eq!(add_watermark(&mut pdf, &opts, &ranges("1,3")).unwrap(), 2);
    let bytes = pdf.to_bytes().unwrap();
    let pdf = open(&bytes);
    let p1 = content_text(&pdf, 1);
    assert!(p1.contains("(DRAFT) Tj"), "{p1}");
    assert!(p1.contains("Page 1"), "original content kept");
    assert!(!content_text(&pdf, 2).contains("DRAFT"));
    // Opacity goes through an ExtGState.
    let doc = pdf.document();
    let page = doc.get_dictionary(doc.get_pages()[&1]).unwrap();
    let res = page.get(b"Resources").unwrap().as_dict().unwrap();
    let gs = res.get(b"ExtGState").unwrap().as_dict().unwrap();
    let (_, gs_ref) = gs.iter().next().unwrap();
    let gs = doc.get_dictionary(gs_ref.as_reference().unwrap()).unwrap();
    assert_eq!(gs.get(b"ca").unwrap().as_float().unwrap(), 0.3);
    // The original font name is still there next to ours.
    assert!(res.get(b"Font").unwrap().as_dict().unwrap().has(b"F1"));
}

#[test]
fn watermark_checks_its_options() {
    let mut pdf = open(&sample_pdf(1));
    let all = PageRanges::all();
    let e = add_watermark(&mut pdf, &WatermarkOptions::default(), &all).unwrap_err();
    assert!(e.to_string().contains("empty"));
    let opts = WatermarkOptions {
        text: "日本".into(),
        ..Default::default()
    };
    assert!(
        add_watermark(&mut pdf, &opts, &all)
            .unwrap_err()
            .to_string()
            .contains("Latin")
    );
    let opts = WatermarkOptions {
        text: "x".into(),
        opacity: 2.0,
        ..Default::default()
    };
    assert!(add_watermark(&mut pdf, &opts, &all).is_err());
    // Latin-1 and typographic quotes are fine.
    let opts = WatermarkOptions {
        text: "Rahasia — “Draf” é".into(),
        ..Default::default()
    };
    add_watermark(&mut pdf, &opts, &all).unwrap();
}

#[test]
fn watermark_twice_keeps_graphics_state_balanced() {
    let mut pdf = open(&sample_pdf(1));
    let opts = WatermarkOptions {
        text: "A".into(),
        ..Default::default()
    };
    add_watermark(&mut pdf, &opts, &PageRanges::all()).unwrap();
    add_watermark(&mut pdf, &opts, &PageRanges::all()).unwrap();
    let text = content_text(&pdf, 1);
    let q = text.split_whitespace().filter(|t| *t == "q").count();
    let big_q = text.split_whitespace().filter(|t| *t == "Q").count();
    assert_eq!(q, big_q, "{text}");
    assert_eq!(text.matches("(A) Tj").count(), 2);
}

/// The Tm translation of the first stamp on page `p`.
fn stamp_origin(pdf: &Pdf, p: u32) -> (f32, f32) {
    let text = content_text(pdf, p);
    let tokens: Vec<&str> = text.split_whitespace().collect();
    let i = tokens.iter().position(|t| *t == "Tm").unwrap();
    (
        tokens[i - 2].parse().unwrap(),
        tokens[i - 1].parse().unwrap(),
    )
}

#[test]
fn page_numbers_follow_format_and_start() {
    let mut pdf = open(&sample_pdf(4));
    let opts = PageNumberOptions {
        format: "{n} of {total}".into(),
        start: 1,
        ..Default::default()
    };
    assert_eq!(add_page_numbers(&mut pdf, &opts, &ranges("2-")).unwrap(), 3);
    let bytes = pdf.to_bytes().unwrap();
    let pdf = open(&bytes);
    assert!(!content_text(&pdf, 1).contains(" of "));
    assert!(content_text(&pdf, 2).contains("(1 of 3) Tj"));
    assert!(content_text(&pdf, 4).contains("(3 of 3) Tj"));
}

#[test]
fn page_number_is_centred_at_the_bottom() {
    let mut pdf = open(&sample_pdf(1));
    add_page_numbers(&mut pdf, &PageNumberOptions::default(), &PageRanges::all()).unwrap();
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (sample_width(1) - w) / 2.0).abs() < 0.01, "x {x}");
    assert!((y - 30.0).abs() < 0.01, "y {y}");
}

#[test]
fn page_number_positions_and_format_errors() {
    let mut pdf = open(&sample_pdf(1));
    let opts = PageNumberOptions {
        position: "top-right".parse().unwrap(),
        ..Default::default()
    };
    add_page_numbers(&mut pdf, &opts, &PageRanges::all()).unwrap();
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (sample_width(1) - 30.0 - w)).abs() < 0.01, "x {x}");
    assert!((y - (800.0 - 30.0 - 12.0 * 0.718)).abs() < 0.01, "y {y}");

    let bad = PageNumberOptions {
        format: "page".into(),
        ..Default::default()
    };
    assert!(add_page_numbers(&mut pdf, &bad, &PageRanges::all()).is_err());
    assert!("sideways".parse::<Position>().is_err());
    assert_eq!(
        "BottomLeft".parse::<Position>().unwrap(),
        Position::BottomLeft
    );
}

#[test]
fn page_numbers_on_rotated_pages_use_the_displayed_bottom() {
    // Page width 601, height 800, /Rotate 90: displayed 800 wide, 601 tall.
    let mut pdf = open(&sample_pdf_inherited(1));
    add_page_numbers(&mut pdf, &PageNumberOptions::default(), &PageRanges::all()).unwrap();
    let text = content_text(&pdf, 1);
    assert!(text.contains("0.0 1.0 -1.0 0.0 601.0 0.0 cm"), "{text}");
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (800.0 - w) / 2.0).abs() < 0.01, "x {x}");
    assert!((y - 30.0).abs() < 0.01);
}

#[test]
fn images_become_pages() {
    let images = vec![
        ("a.png".to_string(), sample_png(40, 20, false)),
        ("b.jpg".to_string(), sample_jpeg(30, 60)),
        ("c.png".to_string(), sample_png(10, 10, true)),
    ];
    let mut pdf = images_to_pdf(&images, &ImageOptions::default()).unwrap();
    let bytes = pdf.to_bytes().unwrap();
    let i = info(&bytes, None).unwrap();
    let sizes: Vec<(f32, f32)> = i.pages.iter().map(|p| (p.width, p.height)).collect();
    assert_eq!(sizes, [(40.0, 20.0), (30.0, 60.0), (10.0, 10.0)]);
    let pdf = open(&bytes);
    let doc = pdf.document();
    let mut filters = Vec::new();
    let mut smasks = 0;
    for obj in doc.objects.values() {
        if let Ok(s) = obj.as_stream()
            && s.dict.get(b"Subtype").and_then(|o| o.as_name()).ok() == Some(b"Image".as_slice())
        {
            filters.push(s.dict.get(b"Filter").unwrap().as_name().unwrap().to_vec());
            if s.dict.has(b"SMask") {
                smasks += 1;
            }
        }
    }
    // The JPEG is embedded as is; PNGs (and the alpha mask) use Flate.
    assert!(filters.contains(&b"DCTDecode".to_vec()));
    assert_eq!(
        filters
            .iter()
            .filter(|f| f.as_slice() == b"FlateDecode")
            .count(),
        3
    );
    assert_eq!(smasks, 1);
}

#[test]
fn images_on_a4_with_margins_fit_and_turn() {
    let images = vec![
        ("wide.png".to_string(), sample_png(400, 100, false)),
        ("tall.png".to_string(), sample_png(100, 400, false)),
    ];
    let opts = ImageOptions {
        page_size: PageSize::A4,
        orientation: Orientation::Auto,
        margin: 36.0,
    };
    let mut pdf = images_to_pdf(&images, &opts).unwrap();
    let bytes = pdf.to_bytes().unwrap();
    let i = info(&bytes, None).unwrap();
    assert!(
        i.pages[0].width > i.pages[0].height,
        "wide image → landscape"
    );
    assert_eq!(i.pages[1].paper_name().as_deref(), Some("A4"));
    // The tall image is scaled to the printable height and centred.
    let text = content_text(&open(&bytes), 2);
    let ah = 841.89 - 72.0;
    let aw = ah / 4.0;
    let expect = format!(
        "{} 0 0 {} {} 36 cm",
        aw,
        ah,
        36.0 + (595.276 - 72.0 - aw) / 2.0
    );
    let got: Vec<f32> = text
        .split_whitespace()
        .take_while(|t| *t != "cm")
        .filter_map(|t| t.parse().ok())
        .collect();
    let want: Vec<f32> = expect
        .split_whitespace()
        .filter_map(|t| t.parse().ok())
        .collect();
    for (g, w) in got.iter().zip(&want) {
        assert!((g - w).abs() < 0.01, "{text} vs {expect}");
    }
}

#[test]
fn images_reject_other_formats_and_bad_margins() {
    let gif = b"GIF89a\x01\x00\x01\x00".to_vec();
    let e = images_to_pdf(&[("x.gif".into(), gif)], &ImageOptions::default()).unwrap_err();
    assert!(e.to_string().contains("x.gif"), "{e}");
    let opts = ImageOptions {
        page_size: PageSize::A4,
        margin: 400.0,
        ..Default::default()
    };
    let e = images_to_pdf(&[("a.png".into(), sample_png(4, 4, false))], &opts).unwrap_err();
    assert!(e.to_string().contains("no room"), "{e}");
    assert!(images_to_pdf(&[], &ImageOptions::default()).is_err());
}

#[test]
fn exif_matrices_map_the_unit_square_upright() {
    // Where the stored image's top-left pixel (u=0, v=1) lands.
    let top_left = |m: [f32; 6]| (m[2] + m[4], m[3] + m[5]);
    let im = crate::images::exif_matrix;
    assert_eq!(top_left(im(1)), (0.0, 1.0));
    assert_eq!(top_left(im(3)), (1.0, 0.0));
    // Orientation 6 is "rotate 90° clockwise to view": top-left goes top-right.
    assert_eq!(top_left(im(6)), (1.0, 1.0));
    assert_eq!(top_left(im(8)), (0.0, 0.0));
}

#[test]
fn compress_merges_duplicates_and_shrinks() {
    // Merging a file with itself duplicates every font and content stream.
    let mut merged = merge(open(&sample_pdf(20)), vec![open(&sample_pdf(20))]).unwrap();
    let original = merged.to_bytes().unwrap();
    let pdf = open(&original);
    let (out, report) = compress(pdf, &original).unwrap();
    assert!(report.duplicates_merged >= 20, "{report:?}");
    assert!(!report.kept_original);
    assert!(report.after < report.before, "{report:?}");
    assert_eq!(out.len(), report.after);
    let mut again = open(&out);
    assert_eq!(again.page_count(), 40);
    assert_eq!(order(&mut again)[..3], [1, 2, 3]);
}

#[test]
fn compress_keeps_the_original_when_it_cannot_win() {
    let mut merged = merge(open(&sample_pdf(3)), vec![]).unwrap();
    let original = merged.to_bytes().unwrap();
    let (once, _) = compress(open(&original), &original).unwrap();
    let (twice, report) = compress(open(&once), &once).unwrap();
    assert!(report.kept_original, "{report:?}");
    assert_eq!(twice, once);
}

#[test]
fn compress_report_percent() {
    let r = CompressReport {
        before: 200,
        after: 150,
        unused_removed: 0,
        duplicates_merged: 0,
        kept_original: false,
    };
    assert_eq!(r.saved_percent(), 25.0);
}
